1	/**
2	 * The eight-cell tone-mark table as one checkable structure (Task 4.1).
3	 *
4	 * The source course spreads mid class (lessons 17-18), high class (21-22) and
5	 * low class (23-24) across six lessons with unrelated material between them.
6	 * The table is small enough to teach as one pattern: mid class takes all four
7	 * marks; high and low class take only mái-èek and mái-thoo; low class is the
8	 * odd one out, giving falling/high where high class gives low/falling.
9	 *
10	 * CONTEXT.md rule 2 — build on, never beside. `completeToneChart.withToneMark`
11	 * already carries this exact table, with `"N/A"` recording the four
12	 * combinations standard spelling never uses. This module reads that chart and
13	 * `toneMarkRules` rather than re-declaring the data, and turns the "N/A"
14	 * shorthand into a queryable three-state result (AC7): a class-and-mark
15	 * combination is `"resolved"`, declared `"unreachable"`, or `"undeclared"` —
16	 * three distinct states, so an unimplemented query never reads the same as an
17	 * impossible one.
18	 *
19	 * `"unreachable"`, not `"impossible"` (AC2): mái-dtrii and mái-jàt-dtà-waa on
20	 * a high- or low-class consonant are writable shapes that turn up in
21	 * loanwords and informal spelling. They are absent from *standard*
22	 * orthography, which is a fact about spelling convention, not about what a
23	 * learner could be shown and told "that can't exist."
24	 */
25	
26	import {
27		completeToneChart,
28		ThaiSymbolClass,
29		type ToneMarkRule,
30		type ToneValue,
31		toneMarkRules,
32		toneRules,
33	} from "./symbols";
34	
35	export type ToneMarkName = "mai ek" | "mai tho" | "mai tri" | "mai chattawa";
36	
37	export const TONE_MARK_NAMES: readonly ToneMarkName[] = Object.freeze([
38		"mai ek",
39		"mai tho",
40		"mai tri",
41		"mai chattawa",
42	]);
43	
44	export const TONE_MARK_TABLE_CLASSES: readonly ThaiSymbolClass[] =
45		Object.freeze([
46			ThaiSymbolClass.Mid,
47			ThaiSymbolClass.High,
48			ThaiSymbolClass.Low,
49		]);
50	
51	export type ToneMarkCellState = "resolved" | "unreachable" | "undeclared";
52	
53	export interface ToneMarkCell {
54		readonly toneMarkName: ToneMarkName;
55		readonly consonantClass: ThaiSymbolClass;
56		readonly state: ToneMarkCellState;
57		readonly resultingTone?: ToneValue;
58		/** Present only when `state` is `"unreachable"`. */
59		readonly note?: string;
60	}
61	
62	const UNREACHABLE_NOTE =
63		"Not used in standard spelling. The shape is writable — it appears in loanwords and informal spelling — but no standard word pairs this mark with this consonant class.";
64	
65	function findRule(
66		toneMarkName: ToneMarkName,
67		consonantClass: ThaiSymbolClass,
68	): ToneMarkRule | undefined {
69		return toneMarkRules.find(
70			(rule) =>
71				rule.toneMarkName === toneMarkName &&
72				rule.consonantClass === consonantClass,
73		);
74	}
75	
76	/**
77	 * `completeToneChart.withToneMark.rules` records `"N/A"` for mid-only marks
78	 * against the `high`/`low` columns — that IS the unreachable set, read off
79	 * the existing chart rather than re-declared.
80	 */
81	function isDeclaredUnreachable(
82		toneMarkName: ToneMarkName,
83		consonantClass: ThaiSymbolClass,
84	): boolean {
85		if (consonantClass === ThaiSymbolClass.Mid) return false;
86		const column = consonantClass === ThaiSymbolClass.High ? "high" : "low";
87		const row = completeToneChart.withToneMark.rules.find((candidate) =>
88			candidate.mark.startsWith(toneMarkName),
89		);
90		return row?.[column] === "N/A";
91	}
92	
93	/** AC1, AC2, AC7 — every class-and-mark combination resolves to exactly one
94	 * of three states, and "unreachable" is a declaration, not an absence. */
95	export function getToneMarkCell(
96		toneMarkName: ToneMarkName,
97		consonantClass: ThaiSymbolClass,
98	): ToneMarkCell {
99		const rule = findRule(toneMarkName, consonantClass);
100		if (rule) {
101			return {
102				toneMarkName,
103				consonantClass,
104				state: "resolved",
105				resultingTone: rule.resultingTone,
106			};
107		}
108		if (isDeclaredUnreachable(toneMarkName, consonantClass)) {
109			return {
110				toneMarkName,
111				consonantClass,
112				state: "unreachable",
113				note: UNREACHABLE_NOTE,
114			};
115		}
116		return { toneMarkName, consonantClass, state: "undeclared" };
117	}
118	
119	/** The full 3-class × 4-mark table the lesson renders — twelve cells. */
120	export function buildToneMarkTable(): ToneMarkCell[] {
121		return TONE_MARK_TABLE_CLASSES.flatMap((consonantClass) =>
122			TONE_MARK_NAMES.map((toneMarkName) =>
123				getToneMarkCell(toneMarkName, consonantClass),
124			),
125		);
126	}
127	
128	export interface SyllableToneQuery {
129		/** The syllable's governing class — for a leading-consonant syllable this
130		 * is the leader's class, not the class of the letter the mark sits over
131		 * (AC3). */
132		readonly governingClass: ThaiSymbolClass;
133		readonly syllableType: "live" | "dead-short" | "dead-long";
134		readonly toneMark?: ToneMarkName;
135	}
136	
137	/**
138	 * AC3 — a tone mark resolves against the governing class and, once resolved,
139	 * the live/dead spelling rule (`toneRules`) is not consulted at all: the mark
140	 * wins outright rather than being weighed against the spelling outcome.
141	 */
142	export function resolveSyllableTone(
143		query: SyllableToneQuery,
144	): ToneValue | undefined {
145		if (query.toneMark) {
146			const cell = getToneMarkCell(query.toneMark, query.governingClass);
147			if (cell.state === "resolved") return cell.resultingTone;
148		}
149		const spellingRule = toneRules.find(
150			(rule) =>
151				rule.consonantClass === query.governingClass &&
152				rule.syllableType === query.syllableType,
153		);
154		return spellingRule?.resultingTone;
155	}
