27	/**
28	 * Task 3.2's proof: the three concepts that actually stop a beginner reading,
29	 * promoted from asides to lessons.
30	 *
31	 * The load-bearing decision is AC4's. Every rule these lessons teach is also
32	 * encoded in `syllableRules.ts`, and resolving a word against *that* would
33	 * pass in precisely the case this task exists to catch: a lesson that states a
34	 * rule incompletely and leaves the learner deriving from material that does
35	 * not reach. So the resolver below is parameterised by facts pulled out of the
36	 * committed decks — the inventory comes off the cluster slides, each unwritten
37	 * vowel is recovered from the worked examples the lesson prints, and the class
38	 * transfer comes off the one slide that states it. `syllableRules.ts` is
39	 * imported only to cross-check that the lessons and the rule module agree
40	 * about the same twenty pairs, ten sonorants and four อ words; it is never
41	 * consulted to read a word.
42	 */
43	
44	const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");
45	const PUBLIC_LESSONS = join(REPO_ROOT, "public", "lessons");
46	
47	const UNWRITTEN = "lesson-unwritten-vowels";
48	const CLUSTERS = "lesson-clusters";
49	const LEADING = "lesson-leading-consonants";
50	
51	/** Declaration order is the order the learner meets them. */
52	const PROMOTED = [
53		{ id: UNWRITTEN, legacyNumber: 26 },
54		{ id: CLUSTERS, legacyNumber: 27 },
55		{ id: LEADING, legacyNumber: 28 },
56	] as const;
57	
58	type RawSlide = {
59		kind: string;
60		id: string;
61		heading?: string;
62		body?: string[];
63		prompt?: string;
64		answers?: string[];
65		revealSlideId?: string;
66		retrievalSlideId?: string;
67		ruleId?: string;
68		audio?: string[];
69		image?: string;
70	};
71	type RawDeck = { lessonId: string; title: string; slides: RawSlide[] };
72	type Manifest = { lessonId: string; assets: { path: string | null }[] };
73	
74	const THAI_RUN = /[฀-๿]+/g;
75	const THAI_LETTER = /[ก-ฮ]/g;
76	
77	function readDeck(id: string): RawDeck {
78		return JSON.parse(
79			readFileSync(join(PUBLIC_LESSONS, id, "deck.json"), "utf-8"),
80		) as RawDeck;
81	}
82	
83	const decks = new Map(PROMOTED.map(({ id }) => [id, readDeck(id)]));
84	
85	function deckFor(id: string): RawDeck {
86		const deck = decks.get(id);
87		if (!deck) throw new Error(`${id}: no committed deck`);
88		return deck;
89	}
90	
91	/**
92	 * A slide by id, or a thrown error naming it.
93	 *
94	 * Not `undefined`: every derivation below reads its facts off a named slide,
95	 * and a renamed slide would otherwise arrive at the resolver as a rule with no
96	 * examples — diagnosed twelve steps later as "the lesson cannot read คน".
97	 */
98	function slide(deckId: string, slideId: string): RawSlide {
99		const found = deckFor(deckId).slides.find((s) => s.id === slideId);
100		if (!found) throw new Error(`${deckId}: no slide "${slideId}"`);
101		return found;
102	}
103	
104	function bodyOf(deckId: string, slideId: string): string[] {
105		return slide(deckId, slideId).body ?? [];
106	}
107	
108	/** Heading and body together — the learner-facing text of one slide. */
109	function textOf(deckId: string, slideId: string): string {
110		const found = slide(deckId, slideId);
111		return [found.heading ?? "", ...(found.body ?? [])].join(" ");
112	}
113	
114	/** Every piece of learner-facing prose on a deck, in slide order. */
115	function textsOf(deck: RawDeck): string[] {
116		const texts: string[] = [deck.title];
117		for (const s of deck.slides) {
118			if (s.heading) texts.push(s.heading);
119			if (s.prompt) texts.push(s.prompt);
120			texts.push(...(s.body ?? []));
121			texts.push(...(s.answers ?? []));
122		}
123		return texts;
124	}
125	
126	// ============================================================================
127	// The alphabet the lessons are allowed to assume
128	// ============================================================================
129	
130	/**
131	 * What a consonant sounds like at the front of a syllable, as a romanization
132	 * token. `initialSound` is prose ("dt (between D and T, unaspirated T)"), and
133	 * its first word is the token every romanization in `vocabulary.json` uses.
134	 *
135	 * Prior material: which letter makes which sound is the alphabet, taught
136	 * across the opening band, and none of the three lessons under test restates
137	 * it.
138	 */
139	function onsetOf(character: string): string {
140		const consonant = getConsonant(character);
141		if (!consonant) throw new Error(`${character} is not a Thai consonant`);
142		return (consonant.initialSound.split(/[\s(]/)[0] ?? "").toLowerCase();
143	}
144	
145	interface FinalReading {
146		readonly sound: string;
147		/** A stop final closes the syllable dead; everything else leaves it live. */
148		readonly stops: boolean;
149	}
150	
151	function finalOf(character: string): FinalReading | undefined {
152		const consonant = getConsonant(character);
153		if (!consonant) return undefined;
154		const raw = consonant.finalSound;
155		if (/not used as final/i.test(raw)) return undefined;
156		const stop = /^([KTP])-stop/.exec(raw);
157		if (stop) return { sound: stop[1].toLowerCase(), stops: true };
158		return { sound: (raw.split(/[\s(]/)[0] ?? "").toLowerCase(), stops: false };
159	}
160	
161	function classOf(character: string): ThaiSymbolClass | undefined {
162		return getConsonant(character)?.classType;
163	}
164	
165	function isConsonant(character: string): boolean {
166		return getConsonant(character) !== undefined;
167	}
168	
169	const TONE_BY_CLASS = new Map(
170		completeToneChart.withoutToneMark.rules.map((rule) => [
171			rule.class.toLowerCase(),
172			rule,
173		]),
174	);
175	
176	/** The no-tone-mark tone table, read off `symbols.ts`. Opening-band material. */
177	function toneFor(
178		consonantClass: ThaiSymbolClass,
179		syllableType: "live" | "dead",
180		length: "short" | "long",
181	): ToneValue {
182		const row = TONE_BY_CLASS.get(consonantClass);
183		if (!row) throw new Error(`no tone row for ${consonantClass}`);
184		if (syllableType === "live") return row.live as ToneValue;
185		return (length === "short" ? row.deadShort : row.deadLong) as ToneValue;
186	}
187	
188	/**
189	 * The written vowels the sample words spell out loud, as romanization and
190	 * length. Prior material again — every one has a symbol on the page and a
191	 * lesson of its own; the three lessons here are about the vowels that do not.
192	 * `theWrittenVowelTableAgreesWithTheAlphabet` holds it to `symbols.ts`.
193	 */
194	const WRITTEN_VOWELS: Readonly<
195		Record<string, { romanization: string; length: "short" | "long" }>
196	> = {
197		ะ: { romanization: "a", length: "short" }, // ะ
198		"ั": { romanization: "a", length: "short" }, // ◌ั
199		า: { romanization: "aa", length: "long" }, // า
200		"ิ": { romanization: "i", length: "short" }, // ◌ิ
201		"ี": { romanization: "ii", length: "long" }, // ◌ี
202		"ุ": { romanization: "u", length: "short" }, // ◌ุ
203		"ู": { romanization: "uu", length: "long" }, // ◌ู
204	};
205	
206	/** Vowels written in front of the consonant they belong to. */
207	const PREPOSED_VOWELS: Readonly<
208		Record<string, { romanization: string; length: "short" | "long" }>
209	> = {
210		ใ: { romanization: "ai", length: "long" }, // ใ
211		ไ: { romanization: "ai", length: "long" }, // ไ
212	};
213	
214	// ============================================================================
215	// Romanization, as the corpus writes it
216	// ============================================================================
217	
218	const TONE_OF_DIACRITIC: Readonly<Record<string, ToneValue>> = {
219		"̀": "low",
220		"́": "high",
221		"̂": "falling",
222		"̌": "rising",
223	};
224	
225	interface RomanSyllable {
226		readonly plain: string;
227		readonly tone: ToneValue;
228	}
229	
230	/** Split a corpus romanization into syllables, each with its tone. */
231	function romanSyllables(romanization: string): RomanSyllable[] {
232		return romanization
233			.split(/[-\s]+/)
234			.filter((part) => part.length > 0)
235			.map((part) => {
236				const decomposed = part.normalize("NFD");
237				let tone: ToneValue = "mid";
238				for (const mark of Object.keys(TONE_OF_DIACRITIC)) {
239					if (decomposed.includes(mark)) tone = TONE_OF_DIACRITIC[mark];
240				}
241				return {
242					plain: decomposed.replace(/[̀-ͯ]/g, ""),
243					tone,
244				};
245			});
246	}
247	
248	// ============================================================================
249	// The rules, read off the lessons
250	// ============================================================================
251	
252	/** `word (romanization)` pairs printed in a slide's prose. */
253	function examplePairs(deckId: string, slideId: string): [string, string][] {
254		const pairs: [string, string][] = [];
255		for (const line of bodyOf(deckId, slideId)) {
256			for (const match of line.matchAll(/([ก-๎]+)\s*\(([^)]+)\)/g)) {
257				pairs.push([match[1], match[2]]);
258			}
259		}
260		return pairs;
261	}
262	
263	/** The vowel length a slide states in its own words. */
264	function statedLength(deckId: string, slideId: string): "short" | "long" {
265		const match = /\b(short|long)\b/.exec(textOf(deckId, slideId));
266		if (!match) {
267			throw new Error(
268				`${deckId}/${slideId}: states no vowel length, so a reader cannot tell live from dead`,
269			);
270		}
271		return match[1] as "short" | "long";
272	}
273	
274	interface UnwrittenVowel {
275		readonly id: string;
276		readonly romanization: string;
277		readonly length: "short" | "long";
278		/** How many examples the derivation agreed across. */
279		readonly evidence: number;
280	}
281	
282	/**
283	 * Recover an unwritten vowel from the worked examples the lesson prints.
284	 *
285	 * The lesson never writes "the vowel is o" in a form a machine could read —
286	 * it prints คน (khon) and five more like it. `shape` says which characters of
287	 * the example are the onset and which is the final; whatever romanization is
288	 * left over in the middle is the vowel the lesson is teaching. Every example
289	 * on the slide has to leave the same residue or the derivation refuses.
290	 */
291	function deriveUnwrittenVowel(
292		slideId: string,
293		shape: (
294			word: string[],
295		) => { onset: string; final: string | null } | undefined,
296	): UnwrittenVowel {
297		const residues = new Set<string>();
298		let evidence = 0;
299		for (const [word, romanization] of examplePairs(UNWRITTEN, slideId)) {
300			const characters = [...word];
301			const parts = shape(characters);
302			if (!parts) continue;
303			const syllables = romanSyllables(romanization);
304			const target = syllables[0];
305			if (!target) continue;
306			if (!target.plain.startsWith(parts.onset)) continue;
307			let middle = target.plain.slice(parts.onset.length);
308			if (parts.final !== null) {
309				if (!middle.endsWith(parts.final)) continue;
310				middle = middle.slice(0, middle.length - parts.final.length);
311			}
312			if (middle.length === 0) continue;
313			residues.add(middle);
314			evidence += 1;
315		}
316		if (residues.size !== 1) {
317			throw new Error(
318				`${UNWRITTEN}/${slideId}: ${evidence} usable example(s) left ${residues.size} different vowels (${[...residues].join(", ")}); the lesson does not state this reading`,
319			);
320		}
321		return {
322			id: slideId,
323			romanization: [...residues][0],
324			length: statedLength(UNWRITTEN, slideId),
325			evidence,
326		};
327	}
328	
329	/** The six readings the unwritten-vowels lesson teaches, derived from it. */
330	function unwrittenVowelsFromLesson() {
331		const implicitO = deriveUnwrittenVowel("implicit-o", (word) =>
332			word.length === 2 && word.every(isConsonant)
333				? { onset: onsetOf(word[0]), final: finalOf(word[1])?.sound ?? null }
334				: undefined,
335		);
336		const implicitA = deriveUnwrittenVowel("implicit-a", (word) =>
337			isConsonant(word[0]) ? { onset: onsetOf(word[0]), final: null } : undefined,
338		);
339		const bareFinalRo = deriveUnwrittenVowel("bare-final-ro", (word) =>
340			word.length === 2 && word[1] === "ร" && isConsonant(word[0])
341				? { onset: onsetOf(word[0]), final: finalOf("ร")?.sound ?? null }
342				: undefined,
343		);
344		const roHan = deriveUnwrittenVowel("ro-han", (word) =>
345			word.length === 4 && word[1] === "ร" && word[2] === "ร"
346				? { onset: onsetOf(word[0]), final: finalOf(word[3])?.sound ?? null }
347				: undefined,
348		);
349		const oAsVowel = deriveUnwrittenVowel("o-as-vowel", (word) =>
350			word.length === 3 && word[1] === "อ" && isConsonant(word[0])
351				? { onset: onsetOf(word[0]), final: finalOf(word[2])?.sound ?? null }
352				: undefined,
353		);
354		const wAsVowel = deriveUnwrittenVowel("w-as-vowel", (word) =>
355			word.length === 3 && word[1] === "ว" && isConsonant(word[0])
356				? { onset: onsetOf(word[0]), final: finalOf(word[2])?.sound ?? null }
357				: undefined,
358		);
359		// อ is the one letter that is a consonant in one position and a vowel in
360		// every other, and the lesson has to say which: without the restriction
361		// ตลอด reads as อ-initial nonsense that scores better than dtà-làawt.
362		const oIsConsonantOnlyAtWordStart =
363			/อ is a consonant only at the front of a word/.test(
364				textOf(UNWRITTEN, "o-as-vowel"),
365			);
366		return {
367			implicitO,
368			implicitA,
369			bareFinalRo,
370			roHan,
371			oAsVowel,
372			wAsVowel,
373			oIsConsonantOnlyAtWordStart,
374		};
375	}
376	
377	type ClusterKind = "true" | "false-sound" | "silent-second" | "lexical";
378	
379	interface LessonCluster {
380		readonly pair: string;
381		readonly kind: ClusterKind;
382		readonly onset: string;
383	}
384	
385	const CLUSTER_SLIDES: Readonly<Record<string, ClusterKind>> = {
386		"true-clusters": "true",
387		"false-sound-clusters": "false-sound",
388		"silent-second-clusters": "silent-second",
389		"lexical-pairs": "lexical",
390	};
391	
392	/** How a true cluster's second letter sounds when both letters are spoken. */
393	const SECOND_LETTER_SOUND: Readonly<Record<string, string>> = {
394		ร: "r",
395		ล: "l",
396		ว: "w",
397	};
398	
399	/**
400	 * The inventory, read off the four slides that list it.
401	 *
402	 * Every two-character Thai run on one of those slides is a pair and every
403	 * longer run is an example word, which is the distinction the lesson's own
404	 * prose makes. A false-sound pair additionally states its sound ("ทร is read
405	 * as s"), and that is parsed rather than assumed, because assuming it would
406	 * let the lesson stop saying it.
407	 */
408	function clustersFromLesson(): Map<string, LessonCluster> {
409		const inventory = new Map<string, LessonCluster>();
410		for (const [slideId, kind] of Object.entries(CLUSTER_SLIDES)) {
411			const lines = bodyOf(CLUSTERS, slideId);
412			const statedSounds = new Map<string, string>();
413			for (const line of lines) {
414				for (const match of line.matchAll(/([ก-ฮ]{2}) is read as ([a-z]+)\b/g)) {
415					statedSounds.set(match[0].slice(0, 2), match[2]);
416				}
417			}
418			for (const line of lines) {
419				for (const run of line.match(THAI_RUN) ?? []) {
420					if ([...run].length !== 2) continue;
421					const [first, second] = [...run];
422					if (!isConsonant(first) || !isConsonant(second)) continue;
423					const onset =
424						kind === "true"
425							? onsetOf(first) + (SECOND_LETTER_SOUND[second] ?? "?")
426							: kind === "false-sound"
427								? (statedSounds.get(run) ?? "?")
428								: onsetOf(first);
429					inventory.set(run, { pair: run, kind, onset });
430				}
431			}
432		}
433		return inventory;
434	}
435	
436	type LeadingBranchId = "silent-h" | "silent-o" | "spoken-leader";
437	
438	interface LessonBranch {
439		readonly id: LeadingBranchId;
440		readonly slideId: string;
441		readonly leaders: readonly string[] | "any-mid-or-high";
442		readonly leaderSpoken: boolean;
443		readonly closed: boolean;
444		readonly words: readonly string[];
445	}
446	
447	/** The single sentence that states the class transfer, and nothing else. */
448	const CLASS_TRANSFER =
449		/\bhands? (?:its|their) class\b|\bpasses (?:its|their) class\b|\bgives (?:its|their) class\b|\bthe leader's class\b/i;
450	const SILENT_LEADER =
451		/\bsilent\b|\bnever spoken\b|\bnot spoken\b|\bnot hear it\b/i;
452	const CLOSED_BRANCH = /\bcomplete list\b|\bno fifth\b|\bno more\b/i;
453	
454	const BRANCH_SLIDES: Readonly<Record<LeadingBranchId, string>> = {
455		"silent-h": "branch-silent-h",
456		"silent-o": "branch-silent-o",
457		"spoken-leader": "branch-spoken-leader",
458	};
459	
460	function leadingRuleFromLesson() {
461		const statement = bodyOf(LEADING, "one-rule").find((line) =>
462			CLASS_TRANSFER.test(line),
463		);
464		if (!statement) {
465			throw new Error(
466				`${LEADING}/one-rule: no line states that the leader hands its class on, so the lesson has no rule`,
467			);
468		}
469		// Not `?? []`: an absent list would make every call to `applyLeadingRule`
470		// answer "that is not a sonorant", which reads as a confident no rather
471		// than as the lesson having stopped saying which letters the rule ranges
472		// over. The statement above refuses the same way and this has to match it.
473		const sonorantLine = bodyOf(LEADING, "why-it-exists").find((line) =>
474			/\bare the sonorants\b/i.test(line),
475		);
476		if (!sonorantLine) {
477			throw new Error(
478				`${LEADING}/why-it-exists: no line names the sonorants, so the rule ranges over nothing`,
479			);
480		}
481		const sonorants = [...(sonorantLine.match(THAI_LETTER) ?? [])];
482	
483		const branches = (Object.keys(BRANCH_SLIDES) as LeadingBranchId[]).map(
484			(id): LessonBranch => {
485				const slideId = BRANCH_SLIDES[id];
486				const text = textOf(LEADING, slideId);
487				const headingLetters = [
488					...((slide(LEADING, slideId).heading ?? "").match(THAI_LETTER) ?? []),
489				];
490				const closed = CLOSED_BRANCH.test(text);
491				const listing = bodyOf(LEADING, slideId).find((line) =>
492					CLOSED_BRANCH.test(line),
493				);
494				return {
495					id,
496					slideId,
497					leaders: headingLetters.length > 0 ? headingLetters : "any-mid-or-high",
498					leaderSpoken: !SILENT_LEADER.test(text),
499					closed,
500					words: closed ? (listing?.match(THAI_RUN) ?? []) : [],
501				};
502			},
503		);
504		return { statement, sonorants, branches };
505	}
506	
507	type LeadingOutcome =
508		| {
509				readonly leads: true;
510				readonly branch: LeadingBranchId;
511				readonly leaderSpoken: boolean;
512				readonly effectiveClass: ThaiSymbolClass;
513		  }
514		| { readonly leads: false; readonly reason: string };
515	
516	/**
517	 * The one code path all three branches go through.
518	 *
519	 * `effectiveClass` is `classOf(leader)` in every branch and is not looked up
520	 * per branch: that identity is exactly what the lesson's single sentence
521	 * claims, so a test that calls this with ห, with อ and with ส and gets three
522	 * right answers out of one statement is the claim, checked.
523	 */
524	function applyLeadingRule(
525		rule: ReturnType<typeof leadingRuleFromLesson>,
526		leader: string,
527		led: string,
528		word?: string,
529	): LeadingOutcome {
530		if (!rule.sonorants.includes(led)) {
531			return { leads: false, reason: `${led} is not one of the sonorants` };
532		}
533		const leaderClass = classOf(leader);
534		if (leaderClass === undefined) {
535			return { leads: false, reason: `${leader} is not a Thai consonant` };
536		}
537		if (
538			leaderClass !== ThaiSymbolClass.Mid &&
539			leaderClass !== ThaiSymbolClass.High
540		) {
541			return { leads: false, reason: `${leader} is low class and leads nothing` };
542		}
543		const named = rule.branches.find(
544			(branch) =>
545				branch.leaders !== "any-mid-or-high" && branch.leaders.includes(leader),
546		);
547		const branch =
548			named ?? rule.branches.find((b) => b.leaders === "any-mid-or-high");
549		if (!branch) return { leads: false, reason: "the lesson declares no branch" };
550		if (branch.closed && word !== undefined && !branch.words.includes(word)) {
551			return {
552				leads: false,
553				reason: `${branch.slideId} is closed at ${branch.words.length} words and ${word} is not one`,
554			};
555		}
556		return {
557			leads: true,
558			branch: branch.id,
559			leaderSpoken: branch.leaderSpoken,
560			effectiveClass: leaderClass,
561		};
562	}
