564	// ============================================================================
565	// Reading a word with nothing but what the three lessons state
566	// ============================================================================
567	
568	interface LessonRules {
569		readonly unwritten: ReturnType<typeof unwrittenVowelsFromLesson>;
570		readonly clusters: Map<string, LessonCluster>;
571		readonly leading: ReturnType<typeof leadingRuleFromLesson>;
572	}
573	
574	function rulesFromLessons(): LessonRules {
575		return {
576			unwritten: unwrittenVowelsFromLesson(),
577			clusters: clustersFromLesson(),
578			leading: leadingRuleFromLesson(),
579		};
580	}
581	
582	interface Syllable {
583		readonly onset: string;
584		readonly initial: string;
585		readonly vowel: string;
586		readonly length: "short" | "long";
587		readonly final: string | null;
588		readonly light: boolean;
589		readonly implicitO: boolean;
590		readonly leader: string | null;
591		tone?: ToneValue;
592		consonantClass?: ThaiSymbolClass;
593	}
594	
595	type Reading = readonly Syllable[];
596	
597	const MAX_READINGS = 256;
598	
599	/**
600	 * Every way the rules allow a syllable to start at `index`.
601	 *
602	 * `leader` is a silent leading consonant the caller has already put through
603	 * the rule. It is passed in rather than peeled off outside because a preposed
604	 * vowel is written before it — ไหล is ไ, then the silent ห, then ล — so the
605	 * leader is not always the first character of its own syllable and a caller
606	 * that assumed it was read ไหล as *hlai*.
607	 */
608	function syllablesAt(
609		rules: LessonRules,
610		characters: readonly string[],
611		index: number,
612		leader?: string,
613	): { syllable: Syllable; length: number }[] {
614		const out: { syllable: Syllable; length: number }[] = [];
615		const here = characters[index];
616		if (here === undefined) return out;
617	
618		const preposed = PREPOSED_VOWELS[here];
619		const onsetStart = index + (preposed ? 1 : 0) + (leader ? 1 : 0);
620		const first = characters[onsetStart];
621		if (first === undefined || !isConsonant(first)) return out;
622		if (
623			first === "อ" &&
624			onsetStart > 0 &&
625			rules.unwritten.oIsConsonantOnlyAtWordStart
626		) {
627			return out;
628		}
629	
630		const onsets: { onset: string; initial: string; width: number }[] = [
631			{ onset: onsetOf(first), initial: first, width: 1 },
632		];
633		const second = characters[onsetStart + 1];
634		if (second !== undefined) {
635			const pair = rules.clusters.get(first + second);
636			// A lexical pair is in the inventory and the lesson says the spelling
637			// does not decide it, so no rule-driven reading may claim it.
638			if (pair && pair.kind !== "lexical") {
639				onsets.push({ onset: pair.onset, initial: first, width: 2 });
640			}
641		}
642	
643		for (const { onset, initial, width } of onsets) {
644			const j = onsetStart + width;
645			const rest = characters.length - onsetStart;
646			const emit = (
647				vowel: string,
648				length: "short" | "long",
649				final: string | null,
650				consumed: number,
651				flags: { light?: boolean; implicitO?: boolean } = {},
652			) => {
653				if (final !== null && !finalOf(final)) return;
654				out.push({
655					syllable: {
656						onset,
657						initial,
658						vowel,
659						length,
660						final,
661						light: flags.light ?? false,
662						implicitO: flags.implicitO ?? false,
663						leader: leader ?? null,
664					},
665					length: j - index + consumed,
666				});
667			};
668	
669			if (preposed) {
670				// A preposed vowel is spelled before its consonant; the rime is the
671				// vowel itself plus an optional final.
672				emit(preposed.romanization, preposed.length, null, 0);
673				const after = characters[j];
674				if (after !== undefined && isConsonant(after)) {
675					emit(preposed.romanization, preposed.length, after, 1);
676				}
677				continue;
678			}
679	
680			const at = characters[j];
681			const written = at === undefined ? undefined : WRITTEN_VOWELS[at];
682			if (written) {
683				emit(written.romanization, written.length, null, 1);
684				const after = characters[j + 1];
685				if (after !== undefined && isConsonant(after)) {
686					emit(written.romanization, written.length, after, 2);
687				}
688			}
689	
690			// อ after the first letter of the word is the long vowel -aaw.
691			if (at === "อ" && j > 0) {
692				const { romanization, length } = rules.unwritten.oAsVowel;
693				emit(romanization, length, null, 1);
694				const after = characters[j + 1];
695				if (after !== undefined && isConsonant(after)) {
696					emit(romanization, length, after, 2);
697				}
698			}
699	
700			// ว with a consonant on each side and no other vowel is the vowel ua.
701			if (at === "ว" && isConsonant(characters[j + 1] ?? "")) {
702				const { romanization, length } = rules.unwritten.wAsVowel;
703				emit(romanization, length, characters[j + 1], 2);
704			}
705	
706			// รร is a vowel: the consonant after it is the final, and with nothing
707			// after it the pair supplies its own n.
708			if (at === "ร" && characters[j + 1] === "ร") {
709				const { romanization, length } = rules.unwritten.roHan;
710				const after = characters[j + 2];
711				if (after !== undefined && isConsonant(after)) {
712					emit(romanization, length, after, 3);
713				} else if (after === undefined) {
714					emit(romanization, length, "น", 2);
715				}
716			}
717	
718			// A word ending on a bare ร ends -aawn.
719			if (at === "ร" && j === characters.length - 1) {
720				const { romanization, length } = rules.unwritten.bareFinalRo;
721				emit(romanization, length, at, 1);
722			}
723	
724			// Two consonants with nothing between them hold a short o.
725			if (at !== undefined && isConsonant(at)) {
726				const { romanization, length } = rules.unwritten.implicitO;
727				emit(romanization, length, at, 1, { implicitO: true });
728			}
729	
730			// A lone consonant that will not fit takes a short a of its own. It is
731			// never the last syllable: a trailing consonant can always be read as a
732			// final, so nothing is left over for it to rescue.
733			if (width === 1 && rest > 1) {
734				const { romanization, length } = rules.unwritten.implicitA;
735				emit(romanization, length, null, 0, { light: true });
736			}
737		}
738		return out;
739	}
740	
741	/** Every complete reading of the word, in no particular order. */
742	function readingsOf(rules: LessonRules, word: string): Reading[] {
743		const characters = [...word];
744		const readings: Syllable[][] = [];
745		const stack: Syllable[] = [];
746	
747		const walk = (index: number): void => {
748			if (readings.length >= MAX_READINGS) return;
749			if (index === characters.length) {
750				readings.push(stack.slice());
751				return;
752			}
753			// A silent leader is written after the preposed vowel, if there is one,
754			// and before the consonant it leads.
755			const leaderAt = index + (PREPOSED_VOWELS[characters[index] ?? ""] ? 1 : 0);
756			const leader = characters[leaderAt];
757			const led = characters[leaderAt + 1];
758			if (leader !== undefined && led !== undefined) {
759				const leading = applyLeadingRule(rules.leading, leader, led, word);
760				if (leading.leads && !leading.leaderSpoken) {
761					for (const option of syllablesAt(rules, characters, index, leader)) {
762						stack.push(option.syllable);
763						walk(index + option.length);
764						stack.pop();
765					}
766				}
767			}
768			for (const option of syllablesAt(rules, characters, index)) {
769				stack.push(option.syllable);
770				walk(index + option.length);
771				stack.pop();
772			}
773		};
774		walk(0);
775		return readings;
776	}
777	
778	/**
779	 * Which of two readings the lesson prefers, in the order `which-reading-wins`
780	 * states it — fewest syllables, then fewest light syllables, then the bare ร
781	 * ending over the unwritten o. "states which reading wins when two of them
782	 * fit" holds the slide to that order.
783	 */
784	function scoreOf(reading: Reading): [number, number, number] {
785		return [
786			reading.length,
787			reading.filter((syllable) => syllable.light).length,
788			reading.filter((syllable) => syllable.implicitO).length,
789		];
790	}
791	
792	function compareReadings(a: Reading, b: Reading): number {
793		const [x, y] = [scoreOf(a), scoreOf(b)];
794		return x[0] - y[0] || x[1] - y[1] || x[2] - y[2];
795	}
796	
797	/** Fill in each syllable's class and tone, applying the class transfer. */
798	function tone(rules: LessonRules, reading: Reading): Syllable[] {
799		const out = reading.map((syllable) => ({ ...syllable }));
800		out.forEach((syllable, index) => {
801			const previous = out[index - 1];
802			let consonantClass = classOf(syllable.initial);
803			if (syllable.leader !== null) {
804				const led = applyLeadingRule(
805					rules.leading,
806					syllable.leader,
807					syllable.initial,
808				);
809				if (led.leads) consonantClass = led.effectiveClass;
810			} else if (previous?.light) {
811				const led = applyLeadingRule(
812					rules.leading,
813					previous.initial,
814					syllable.initial,
815				);
816				if (led.leads && led.leaderSpoken) consonantClass = led.effectiveClass;
817			}
818			if (consonantClass === undefined) return;
819			const finalReading = syllable.final ? finalOf(syllable.final) : undefined;
820			const syllableType: "live" | "dead" = syllable.final
821				? finalReading?.stops
822					? "dead"
823					: "live"
824				: syllable.length === "long"
825					? "live"
826					: "dead";
827			syllable.consonantClass = consonantClass;
828			syllable.tone = toneFor(consonantClass, syllableType, syllable.length);
829		});
830		return out;
831	}
832	
833	type LessonReading =
834		| { readonly state: "read"; readonly syllables: readonly Syllable[] }
835		| { readonly state: "unreadable"; readonly reason: string };
836	
837	/** Read a written Thai word using only what the three lessons state. */
838	function readWord(rules: LessonRules, word: string): LessonReading {
839		const readings = readingsOf(rules, word);
840		if (readings.length === 0) {
841			return {
842				state: "unreadable",
843				reason: "the lessons state no reading that consumes the whole word",
844			};
845		}
846		const best = readings.reduce((a, b) => (compareReadings(a, b) <= 0 ? a : b));
847		const resolved = tone(rules, best);
848		if (resolved.some((syllable) => syllable.tone === undefined)) {
849			return { state: "unreadable", reason: "a syllable has no class" };
850		}
851		return { state: "read", syllables: resolved };
852	}
