120	export type LessonContentResolution =
121		/** Declared, and its content source is known. */
122		| { readonly status: "resolved"; readonly content: LessonContent }
123		/** Declared, but no content source can be produced — with the reason. */
124		| { readonly status: "unresolvable"; readonly reason: string }
125		/** No lesson with this id is declared at all. */
126		| { readonly status: "undeclared" };
127	
128	/**
129	 * The three statuses are distinct values on purpose: a lesson whose video is
130	 * missing must never be indistinguishable from a lesson that does not exist,
131	 * because the first is a broken build and the second is an ordinary 404.
132	 */
133	export const LESSON_CONTENT_STATUSES = [
134		"resolved",
135		"unresolvable",
136		"undeclared",
137	] as const;
