152			if (!path.ok) return { status: "unresolvable", reason: path.error };
153			return {
154				status: "resolved",
155				content: { kind: "deck", deckPath: path.path },
156			};
157		}
158		if (!lesson) {
159			return {
160				status: "unresolvable",
161				reason:
162					"lessonId: declared in the sequence but absent from the lessons table",
163			};
164		}
165		if (!lesson.videoUrl) {
166			return {
167				status: "unresolvable",
168				reason: "lessonId: declares neither a deck nor a video url",
169			};
170		}
171		return {
172			status: "resolved",
173			content: { kind: "video", url: lesson.videoUrl },
174		};
175	}
