178		const lookup = lessonEntryById(value);
179		if (!lookup.ok) return { status: "undeclared" };
180		const entry = lookup.entry;
181		return lessonContentFor(
182			entry,
183			lessons.find((lesson) => lesson.number === entry.legacyNumber),
184		);
185	}
186	
187	// ============================================================================
188	// The rules block
189	// ============================================================================
190	
191	/**
192	 * A rule a lesson teaches, resolved from the tables that already declare it
193	 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
194	 * Rule slides render from this — they carry no prose of their own, so the
195	 * slide and the rule cannot drift apart.
196	 */
197	export interface LessonRule {
198		readonly id: string;
199		readonly kind: "tone" | "special";
200		readonly title: string;
201		readonly text: string;
202	}
203	
204	export function lessonRules(legacyNumber: number): readonly LessonRule[] {
205		const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
206		if (!lesson) return [];
207	
208		const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
209			const rule = toneRules.find((candidate) => candidate.id === id);
210			if (!rule) return [];
211			return [
212				{
213					id: rule.id,
214					kind: "tone",
215					title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
216					text: rule.description,
217				},
218			];
219		});
220		const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
221			const rule = specialRules.find((candidate) => candidate.id === id);
222			if (!rule) return [];
223			return [
224				{
225					id: rule.id,
226					kind: "special",
227					title: rule.title,
228					text: rule.description,
229				},
230			];
231		});
232		return [...tone, ...special];
233	}
234	
235	// ============================================================================
236	// The deck schema
237	// ============================================================================
238	
239	export interface DeckExpositionSlide {
240		readonly kind: "exposition";
241		readonly id: string;
242		readonly heading: string;
243		readonly body: readonly string[];
244	}
245	
246	/**
247	 * A prompt the learner attempts. It names the reveal that answers it and
248	 * carries no answer itself — the attempt is the mechanism, so an answer
249	 * sitting on the same slide defeats the slide entirely.
250	 */
251	export interface DeckRetrievalSlide {
252		readonly kind: "retrieval";
253		readonly id: string;
254		readonly prompt: string;
255		readonly revealSlideId: string;
256	}
257	
258	export interface DeckRevealSlide {
259		readonly kind: "reveal";
260		readonly id: string;
261		readonly retrievalSlideId: string;
262		readonly answers: readonly string[];
263	}
264	
265	/** Renders from the lesson's rules block; holds no prose of its own. */
266	export interface DeckRuleSlide {
267		readonly kind: "rule";
268		readonly id: string;
269		readonly ruleId: string;
270	}
271	
272	export type DeckSlide =
273		| DeckExpositionSlide
274		| DeckRetrievalSlide
275		| DeckRevealSlide
276		| DeckRuleSlide;
277	
278	export interface LessonDeck {
279		readonly lessonId: string;
280		readonly title: string;
281		readonly slides: readonly DeckSlide[];
282	}
283	
284	export type DeckErrorCode =
285		| "malformed"
286		| "lesson-id-refused"
287		| "duplicate-slide-id"
288		| "retrieval-answer-on-same-slide"
289		| "dangling-reveal"
290		| "reveal-before-retrieval"
291		| "missing-retrieval"
292		| "unknown-rule"
293		| "rule-slide-carries-prose";
294	
295	export interface DeckValidationError {
296		readonly code: DeckErrorCode;
297		readonly message: string;
298		readonly slideId?: string;
299	}
300	
301	export type DeckValidationResult =
302		| { readonly ok: true; readonly deck: LessonDeck }
303		| { readonly ok: false; readonly errors: readonly DeckValidationError[] };
304	
305	/** Keys that would put an answer on the retrieval slide itself. */
306	const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
307	/** Keys that would let a rule slide state a rule differently from the block. */
308	const PROSE_KEYS = ["heading", "body", "text", "description"] as const;
309	
310	function isRecord(value: unknown): value is Record<string, unknown> {
311		return typeof value === "object" && value !== null && !Array.isArray(value);
312	}
313	
314	function isStringArray(value: unknown): value is string[] {
315		return (
316			Array.isArray(value) && value.every((item) => typeof item === "string")
317		);
318	}
319	
320	function parseSlide(
321		raw: unknown,
322		index: number,
323		errors: DeckValidationError[],
324	): DeckSlide | undefined {
325		const at = `slides[${index}]`;
326		if (!isRecord(raw)) {
327			errors.push({ code: "malformed", message: `${at}: not an object` });
328			return undefined;
329		}
330		const id = raw.id;
331		if (typeof id !== "string" || id.length === 0) {
332			errors.push({ code: "malformed", message: `${at}: missing a string id` });
333			return undefined;
334		}
335	
336		switch (raw.kind) {
337			case "exposition": {
338				if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
339					errors.push({
340						code: "malformed",
341						slideId: id,
342						message: `${at}: an exposition slide needs a heading and a body of strings`,
343					});
344					return undefined;
345				}
346				return { kind: "exposition", id, heading: raw.heading, body: raw.body };
347			}
348			case "retrieval": {
349				if (
350					typeof raw.prompt !== "string" ||
351					typeof raw.revealSlideId !== "string"
352				) {
353					errors.push({
354						code: "malformed",
355						slideId: id,
356						message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
357					});
358					return undefined;
359				}
360				const leaked = ANSWER_KEYS.find((key) => key in raw);
361				if (leaked) {
362					errors.push({
363						code: "retrieval-answer-on-same-slide",
364						slideId: id,
365						message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
366					});
367					return undefined;
368				}
369				return {
370					kind: "retrieval",
371					id,
372					prompt: raw.prompt,
373					revealSlideId: raw.revealSlideId,
374				};
375			}
376			case "reveal": {
377				if (
378					typeof raw.retrievalSlideId !== "string" ||
379					!isStringArray(raw.answers)
380				) {
381					errors.push({
382						code: "malformed",
383						slideId: id,
384						message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
385					});
386					return undefined;
387				}
388				return {
389					kind: "reveal",
390					id,
391					retrievalSlideId: raw.retrievalSlideId,
392					answers: raw.answers,
393				};
394			}
395			case "rule": {
396				if (typeof raw.ruleId !== "string") {
397					errors.push({
398						code: "malformed",
399						slideId: id,
400						message: `${at}: a rule slide needs a ruleId`,
401					});
402					return undefined;
403				}
404				const prose = PROSE_KEYS.find((key) => key in raw);
405				if (prose) {
406					errors.push({
407						code: "rule-slide-carries-prose",
408						slideId: id,
409						message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
410					});
411					return undefined;
412				}
413				return { kind: "rule", id, ruleId: raw.ruleId };
414			}
415			default:
416				errors.push({
417					code: "malformed",
418					slideId: id,
419					message: `${at}: unknown slide kind`,
420				});
421				return undefined;
422		}
423	}
424	
425	function checkRetrieval(
426		slides: readonly DeckSlide[],
427		errors: DeckValidationError[],
428	): void {
429		const retrievalsSeen = new Set<string>();
430		let pairs = 0;
431	
432		for (const slide of slides) {
433			if (slide.kind === "retrieval") {
434				retrievalsSeen.add(slide.id);
435				continue;
436			}
437			if (slide.kind !== "reveal") continue;
438	
439			const target = slides.find(
440				(candidate) =>
441					candidate.kind === "retrieval" &&
442					candidate.id === slide.retrievalSlideId,
443			);
444			if (!target) {
445				errors.push({
446					code: "dangling-reveal",
447					slideId: slide.id,
448					message: `reveal "${slide.id}" names no retrieval slide that exists`,
449				});
450				continue;
451			}
452			if (!retrievalsSeen.has(slide.retrievalSlideId)) {
453				errors.push({
454					code: "reveal-before-retrieval",
455					slideId: slide.id,
456					message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
457				});
458				continue;
459			}
460			pairs += 1;
461		}
462	
463		if (pairs === 0) {
464			errors.push({
465				code: "missing-retrieval",
466				message:
467					"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
468			});
469		}
470	}
471	
472	export function validateDeck(value: unknown): DeckValidationResult {
473		const errors: DeckValidationError[] = [];
474	
475		if (!isRecord(value)) {
476			return {
477				ok: false,
478				errors: [{ code: "malformed", message: "deck: not an object" }],
479			};
480		}
481		const lessonId = parseLessonId(value.lessonId, "lessonId");
482		if (!lessonId.ok) {
483			return {
484				ok: false,
485				errors: [{ code: "lesson-id-refused", message: lessonId.error }],
486			};
487		}
488		if (typeof value.title !== "string" || value.title.length === 0) {
489			errors.push({ code: "malformed", message: "deck: missing a title" });
490		}
491		if (!Array.isArray(value.slides)) {
492			return {
493				ok: false,
494				errors: [
495					...errors,
496					{ code: "malformed", message: "deck: slides must be an array" },
497				],
498			};
499		}
500	
501		const slides: DeckSlide[] = [];
502		const seenIds = new Set<string>();
503		value.slides.forEach((raw, index) => {
504			const slide = parseSlide(raw, index, errors);
505			if (!slide) return;
506			if (seenIds.has(slide.id)) {
507				errors.push({
508					code: "duplicate-slide-id",
509					slideId: slide.id,
510					message: `slides[${index}]: slide id is already used`,
511				});
512				return;
513			}
514			seenIds.add(slide.id);
515			slides.push(slide);
516		});
517	
518		checkRetrieval(slides, errors);
519	
520		const entry = lessonEntryById(lessonId.id);
521		const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
522		for (const slide of slides) {
523			if (slide.kind !== "rule") continue;
524			if (!rules.some((rule) => rule.id === slide.ruleId)) {
525				errors.push({
526					code: "unknown-rule",
527					slideId: slide.id,
528					message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
529				});
530			}
531		}
532	
533		if (errors.length > 0) return { ok: false, errors };
534		return {
535			ok: true,
536			deck: { lessonId: lessonId.id, title: value.title as string, slides },
537		};
538	}
539	
540	/**
541	 * The rendering source for a rule slide: the lesson's own rules-block entry.
542	 * There is no other text on the slide, which is what makes "the lesson applies
543	 * the rule as it states it" checkable at all.
544	 */
545	export function renderRuleSlide(
546		deck: LessonDeck,
547		slide: DeckRuleSlide,
548	): LessonRule | undefined {
549		const entry = lessonEntryById(deck.lessonId);
550		if (!entry.ok) return undefined;
551		return lessonRules(entry.entry.legacyNumber).find(
552			(rule) => rule.id === slide.ruleId,
553		);
554	}
