	{ thai: "ไก่", toneMarkName: "mai ek", consonantClass: ThaiSymbolClass.Mid },
	{ thai: "เก้า", toneMarkName: "mai tho", consonantClass: ThaiSymbolClass.Mid },
	{ thai: "โต๊ะ", toneMarkName: "mai tri", consonantClass: ThaiSymbolClass.Mid },
	{
