});

// ============================================================================
// AC6 — assets
// ============================================================================

describe("AC6 — every asset the deck references exists", () => {
	it("references only files inside the lesson's own directory, and leaves none unreferenced", () => {
		const directory = join(PUBLIC_LESSONS, LESSON_ID);
