		expect(existsSync(join(directory, "manifest.json"))).toBe(true);

		const manifest = JSON.parse(
			readFileSync(join(directory, "manifest.json"), "utf-8"),
		) as Manifest;
		expect(manifest.lessonId).toBe(LESSON_ID);

